import { getKatex } from './katexLoader'

const cache = new Map<string, string>()

/**
 * Render LaTeX to markup with KaTeX. `trust: false` disables \href, \url,
 * \includegraphics and \html*, so output is generated by KaTeX alone and never
 * echoes raw model HTML (NFR §6.2).
 */
export function renderTex(latex: string, display: boolean): string | null {
  const katex = getKatex()
  if (!katex) return null
  const key = `${display ? 'D' : 'I'}:${latex}`
  let html = cache.get(key)
  if (html === undefined) {
    html = katex.renderToString(latex, {
      displayMode: display,
      throwOnError: false,
      trust: false,
      strict: 'ignore',
      maxExpand: 200,
      maxSize: 20,
    })
    if (cache.size > 500) cache.clear()
    cache.set(key, html)
  }
  return html
}
